service.method:

INSERT INTO SGWAH 
( 
    HOUSE_CODE 
  , COMPANY_CODE 
  , LINE_TYPE 
  , APP_TYPE 
  , CODE 
  , LINE_TYPE_NAME 
  , ADD_DATE 
  , ADD_TIME 
  , ADD_USER_ID 
  , CHANGE_DATE 
  , CHANGE_TIME 
  , CHANGE_USER_ID  
) 
VALUES 
( 
    ${session.HOUSE_CODE} 
  , ${session.COMPANY_CODE} 
  , ${LINE_TYPE} 
  , ${APP_TYPE} 
  , ${CODE} 
  , ${LINE_TYPE_NAME} 
  , ${current.date} 
  , ${current.time} 
  , ${session.ID} 
  , ${current.date} 
  , ${current.time} 
  , ${session.ID}  
)


INSERT INTO SGWAD 
( 
    HOUSE_CODE
  , COMPANY_CODE
  , LINE_TYPE
  , APP_TYPE
  , CODE
  , LINE_SEQ
  , USER_ID
  , APP_USER_AMT
  , ADD_DATE
  , ADD_TIME
  , ADD_USER_ID
  , CHANGE_DATE
  , CHANGE_TIME
  , CHANGE_USER_ID
  , USE_FLAG
) 
VALUES 
( 
    ${session.HOUSE_CODE} 
  , ${session.COMPANY_CODE} 
  , ${LINE_TYPE}
  , ${APP_TYPE}
  , ${CODE}
  , ${LINE_SEQ}
  , ${USER_ID}
  , ${APP_USER_AMT}
  , ${current.date} 
  , ${current.time} 
  , ${session.ID} 
  , ${current.date} 
  , ${current.time} 
  , ${session.ID} 
  , ${USE_FLAG}
)


DELETE 
  FROM SGWAH 
 WHERE 1 = 1 
       AND HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${session.COMPANY_CODE} 
       AND LINE_TYPE = ${LINE_TYPE} 
       AND APP_TYPE = ${APP_TYPE} 
       AND CODE = ${CODE}


DELETE 
  FROM SGWAD 
 WHERE 1 = 1 
       AND HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${session.COMPANY_CODE} 
       AND LINE_TYPE = ${LINE_TYPE} 
       AND APP_TYPE = ${APP_TYPE} 
       AND CODE = ${CODE}


DELETE 
  FROM SGWAD 
 WHERE 1 = 1 
       AND HOUSE_CODE = ${session.HOUSE_CODE} 
       AND COMPANY_CODE = ${session.COMPANY_CODE} 
       AND LINE_TYPE = ${LINE_TYPE} 
       AND APP_TYPE = ${APP_TYPE} 
       AND CODE = ${CODE}
       AND LINE_SEQ = ${LINE_SEQ}
